export function sfwBatchSystemPrompt(card: SfwBatchCard): string {
  return [
    `You are ${card.name}, a fictional adult (${card.age}+).`,
    `Setting: ${card.location}. Title beat: "${card.title}".`,
    card.personality,
    SFW_BATCH_STAKE[card.genre],
    'Stay SFW: no explicit sexual content, no nudity. Invite the other person to act; do not decide their choices.',
    `Genre tags: ${SFW_BATCH_GENRE_LABEL[card.genre]}.`,
  ].join(' ');
}

export function sfwBatchCreatorNotes(card: SfwBatchCard): string {
  return [
    `Title: ${card.title}`,
    `Genre: ${card.genre}`,
    `Rating: sfw`,
    `Location: ${card.location}`,
    `Profile: ${card.profile_summary}`,
    `Sayings: ${card.sayings.join(' | ')}`,
  ].join('\n');
}

export function sfwBatchExampleDialogue(card: SfwBatchCard): string {
  return [
    `{{user}}: What is this place to you?\n{{char}}: *stays at ${card.location}* "${card.sayings[0]}"`,
    `{{user}}: You look busy.\n{{char}}: *does not block the exit* "${card.sayings[1]}"`,
    `{{user}}: What should I know before I stay?\n{{char}}: "${card.sayings[2]}"`,
  ].join('\n\n');
}

export function assertSfwBatchRoster(): void {
  if (SFW_BATCH_CARDS.length !== 50) throw new Error(`Expected 50 SFW cards, found ${SFW_BATCH_CARDS.length}`);
  const names = new Set<string>();
  const ids = new Set<string>();
  for (const card of SFW_BATCH_CARDS) {
    if (card.rating !== 'sfw' || card.is_nsfw !== false) throw new Error(`${card.name} must be SFW`);
    if (card.age < 24) throw new Error(`${card.name} must be clearly adult-framed`);
    if (names.has(card.name)) throw new Error(`Duplicate name ${card.name}`);
    if (ids.has(card.id)) throw new Error(`Duplicate id ${card.id}`);
    names.add(card.name);
    ids.add(card.id);
    for (const field of [card.bio, card.personality, card.scenario, card.greeting, card.profile_summary] as const) {
      if (!field || field.length < 180 || field.split(/[.!?]/).filter(Boolean).length < 3) {
        throw new Error(`Field too thin on ${card.name}`);
      }
    }
    if (!card.image_prompt || card.image_prompt.length < 280) {
      throw new Error(`image_prompt too thin on ${card.name}`);
    }
    if (!/2\.5D|semi-realistic|character card/i.test(card.image_prompt)) {
      throw new Error(`image_prompt missing card-sheet style on ${card.name}`);
    }
    if (card.sayings.length < 3) throw new Error(`Need sayings on ${card.name}`);
    if (/\b(nude|lingerie|explicit sex|topless|bottomless)\b/i.test(`${card.bio} ${card.personality} ${card.scenario} ${card.greeting}`)) {
      throw new Error(`SFW violation language on ${card.name}`);
    }
    if (!/fully dressed|modest outfit|opaque/i.test(card.image_prompt)) {
      throw new Error(`image_prompt missing SFW clothing anchors on ${card.name}`);
    }
  }
}
